import{_ as r,o as e,c as a,ag as o}from"./chunks/framework.Aev9KvMf.js";const p=JSON.parse('{"title":"GB 28050 预包装食品营养标签通则 · 看懂标签","description":"国标科普试点：GB 28050 强制标示\\"1+4\\"、NRV% 怎么读，买包装食品前 10 秒看懂营养标签，出处为国家标准全文公开系统。","frontmatter":{"title":"GB 28050 预包装食品营养标签通则 · 看懂标签","issuer":"国家标准化管理委员会 / 原卫生部","source_tier":"一级来源","version":"GB 28050—2011","published":2011,"source_url":"https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=28050","status":"现行","tags":["国标","营养标签","看标签","行动清单"],"type":"国标科普","reviewed":false,"description":"国标科普试点：GB 28050 强制标示\\"1+4\\"、NRV% 怎么读，买包装食品前 10 秒看懂营养标签，出处为国家标准全文公开系统。"},"headers":[],"relativePath":"standards/gb28050-nutrition-label.md","filePath":"standards/gb28050-nutrition-label.md"}'),d={name:"standards/gb28050-nutrition-label.md"};function s(n,t,l,h,g,i){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="gb-28050-预包装食品营养标签通则-·-看懂标签" tabindex="-1">GB 28050 预包装食品营养标签通则 · 看懂标签 <a class="header-anchor" href="#gb-28050-预包装食品营养标签通则-·-看懂标签" aria-label="Permalink to &quot;GB 28050 预包装食品营养标签通则 · 看懂标签&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据国家标准公开文本整理，尚未逐条对照原文校验；校验通过前请以标准原文为准。标准文本可在<a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=28050" target="_blank" rel="noreferrer">国家标准全文公开系统</a>免费在线阅览。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有内容均<strong>整理自国家标准文本</strong>；标注【本站提示】的少数条目为中性工具提示。本站不构成诊疗建议。</p></div><blockquote><p><strong>标准出处</strong>：GB 28050—2011《食品安全国家标准 预包装食品营养标签通则》（<a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=28050" target="_blank" rel="noreferrer">国家标准全文公开系统查询</a>）· 一级来源。<strong>本页是本站&quot;国标科普域&quot;的第一篇试点。</strong></p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p><strong>强制标示 = &quot;1 + 4&quot;</strong>：每包预包装食品的营养成分表<strong>必须</strong>标示 <a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=28050" target="_blank" rel="noreferrer">能量 + 蛋白质、脂肪、碳水化合物、钠</a> 及其占 NRV 的百分比。看不到这张表的预包装食品，要么属于豁免范围，要么不合规。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要点</th><th>内容</th><th>出处</th></tr></thead><tbody><tr><td>强制&quot;1+4&quot;</td><td>能量 + 蛋白质、脂肪、碳水化合物、钠 及 NRV%</td><td><a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=28050" target="_blank" rel="noreferrer">标准正文</a></td></tr><tr><td>NRV%</td><td>占&quot;营养素参考值&quot;的百分比——一天 2000kcal 膳食的参考基准</td><td><a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=28050" target="_blank" rel="noreferrer">标准正文</a></td></tr><tr><td>标示基准</td><td>以每 100g（或每 100mL、每份）为单位标示</td><td><a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=28050" target="_blank" rel="noreferrer">标准正文</a></td></tr><tr><td>营养声称</td><td>想标&quot;低糖&quot;&quot;高钙&quot;等声称或强调某成分，必须完整标示营养成分表</td><td><a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=28050" target="_blank" rel="noreferrer">标准正文</a></td></tr><tr><td>豁免</td><td>每日食用量 ≤10g/10mL 的食品、生鲜、现制现售等可豁免</td><td><a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=28050" target="_blank" rel="noreferrer">标准正文</a></td></tr></tbody></table><h2 id="行动清单-买之前-10-秒看标签" tabindex="-1">行动清单：买之前 10 秒看标签 <a class="header-anchor" href="#行动清单-买之前-10-秒看标签" aria-label="Permalink to &quot;行动清单：买之前 10 秒看标签&quot;">​</a></h2><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>先看钠：NRV% 高于 30% 的每 100g 食品，一包下去钠就过半——控盐家庭重点盯这行</td><td>【本站提示】结合 <a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=28050" target="_blank" rel="noreferrer">GB 28050</a> 的钠强制标示</td></tr><tr><td>再看碳水/糖与脂肪：减重、控糖、控脂家庭对应核对</td><td>【本站提示】数据基础来自营养成分表强制标示</td></tr><tr><td>注意基准是&quot;每 100g&quot;还是&quot;每份&quot;——每份 25g 的薯片标注值要乘以 4 才是一整包</td><td>【本站提示】依据&quot;以每 100g 或每份标示&quot;的规则</td></tr><tr><td>配料表按含量降序：排前几位的是主要成分</td><td>【本站提示】标签规则来自 GB 7718 预包装食品标签通则（后续词条）</td></tr></tbody></table><h2 id="与本站的关系" tabindex="-1">与本站的关系 <a class="header-anchor" href="#与本站的关系" aria-label="Permalink to &quot;与本站的关系&quot;">​</a></h2><p>各食养指南词条里&quot;【本站提示】看营养成分表钠一栏&quot;的技能，本页就是它的国家标准依据。后续国标科普域将覆盖 <a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=7718" target="_blank" rel="noreferrer">GB 7718 标签通则</a> 等常见标准。</p><h2 id="新版动态-版本受控" tabindex="-1">新版动态（版本受控） <a class="header-anchor" href="#新版动态-版本受控" aria-label="Permalink to &quot;新版动态（版本受控）&quot;">​</a></h2><ul><li><strong>GB 28050—2025 已于 2025 年 3 月 16 日发布，2027 年 3 月 16 日实施</strong>（与 GB 7718—2025 同批，<a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">国家卫健委问答</a>）。过渡期内 2011 版仍现行；实施日后生产的食品按新标准标示。</li><li><strong>强制标示将从&quot;1+4&quot;扩展为&quot;1+6&quot;</strong>：新增<strong>糖</strong>和<strong>饱和脂肪</strong>；营养成分表下方将强制标示&quot;儿童青少年应避免过量摄入盐油糖&quot;提示语。逐条对比见<a href="/SageRelay/standards/gb28050-2025-preview.html">标签要变什么·新旧对比</a>（来源：官方问答）。</li><li>本站将在新版实施前逐条核验并更新本词条，2011 版归档不删除。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>标准号</td><td>GB 28050—2011（现行；如发布新版以新版为准）</td></tr><tr><td>归口</td><td>国家卫生健康委（食品安全国家标准）</td></tr><tr><td>全文阅览</td><td><a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=28050" target="_blank" rel="noreferrer">国家标准全文公开系统</a></td></tr></tbody></table>',16)])])}const u=r(d,[["render",s]]);export{p as __pageData,u as default};
